import math

def expected_start_loss(C):
    return math.log(C)

def early_stopping(val, patience):
    best, best_epoch, waited = float('inf'), 0, 0
    for epoch, v in enumerate(val):
        if v < best:
            best, best_epoch, waited = v, epoch, 0
        else:
            waited += 1
            if waited == patience:
                return best_epoch, epoch
    return best_epoch, len(val) - 1
